"""Kontrak snapshot lokal; generator menyematkan helper ini ke export komponen."""
import hashlib
import json
import math
import os
import re
import secrets
import time
import tempfile
from pathlib import Path
from datetime import datetime, timedelta, timezone


def snapshot_digest(payload):
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")).hexdigest()


def save_snapshot(payload):
    directory = Path(os.environ.get("SIGAP_SNAPSHOT_DIR", "output/.sigap_snapshots")).expanduser()
    directory.mkdir(parents=True, exist_ok=True)
    identifier = secrets.token_hex(16)
    digest = snapshot_digest(payload)
    envelope = {"created_at": time.time(), "sha256": digest, "payload": payload}
    with (directory / (identifier + ".json")).open("x", encoding="utf-8") as stream:
        json.dump(envelope, stream, ensure_ascii=False, allow_nan=False)
    return {"snapshot_id": identifier, "snapshot_sha256": digest}


def save_candidate_snapshot(payload):
    """Each shelter gets its own immutable approval reference, using Python's canonical digest."""
    if len(payload.get('records', [])) > 1:
        references=[]
        for record in payload['records']:
            child=dict(payload,records=[record],report_records=[r for r in payload.get('report_records',[]) if r.get('report_id')==record.get('report_id')],
                       issues=[i for i in payload.get('issues',[]) if not i.get('report_id') or i.get('report_id')==record.get('report_id')],
                       snapshot_issues=[i for i in payload.get('snapshot_issues',[]) if not i.get('report_id') or i.get('report_id')==record.get('report_id')])
            references.append(save_snapshot(child))
        payload=dict(payload,row_snapshot_refs=references)
    return save_snapshot(payload)


def load_snapshot(request):
    if not isinstance(request, dict) or not re.fullmatch(r"[a-f0-9]{32}", str(request.get("snapshot_id", ""))):
        raise ValueError("Gunakan snapshot_id dari validate_needs; JSON records bebas tidak diterima.")
    if any(key in request for key in ("records", "stock", "stock_context", "snapshot_records")):
        raise ValueError("Jangan mengirim ulang/mengubah records atau stok. Gunakan referensi snapshot; koreksi harus melalui validate_needs lagi.")
    path = Path(os.environ.get("SIGAP_SNAPSHOT_DIR", "output/.sigap_snapshots")).expanduser() / (request["snapshot_id"] + ".json")
    try:
        envelope = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise ValueError("Snapshot tidak tersedia; semua flow harus memakai SIGAP_SNAPSHOT_DIR yang sama. Validasi ulang bila kedaluwarsa/hilang.") from exc
    if not isinstance(envelope, dict) or not isinstance(envelope.get("payload"), dict) or not isinstance(envelope.get("created_at"), (int, float)) or not isinstance(envelope.get("sha256"), str):
        raise ValueError("File snapshot rusak; jalankan prepare/validate ulang.")
    digest = snapshot_digest(envelope["payload"])
    if digest != envelope["sha256"] or request.get("snapshot_sha256") != digest:
        raise ValueError("Hash snapshot tidak cocok; data berubah atau referensi salah. Validasi dan tampilkan ulang.")
    if time.time() - envelope["created_at"] > 86400:
        raise ValueError("Snapshot kedaluwarsa (24 jam); validasi dan persetujuan ulang diperlukan.")
    committed = path.with_suffix(".committed.json")
    if committed.exists():
        try:
            reference = json.loads(committed.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise ValueError("Status revisi snapshot tidak dapat dibaca; lakukan read-back.") from exc
        raise ValueError("Snapshot telah disimpan/direvisi. Gunakan referensi efektif: " + json.dumps(reference))
    return envelope["payload"]


def quality_status(record):
    if any(record.get(k) for k in ("validation_issues", "unverified_numbers", "stock_issues", "storage_issues", "pending_clear_fields")):
        return "PERLU_KLARIFIKASI"
    required = ("shelter_name", "village", "total_people", "male", "female", "infants_toddlers", "elderly", "pregnant", "breastfeeding", "disability")
    if record.get("missing_fields") or any(record.get(k) is None or record.get(k) == "" for k in required):
        return "PARSIAL"
    return "LOLOS_PEMERIKSAAN"


def clear_options(records):
    actions = {r["report_id"]: list(r.get("pending_clear_fields", [])) for r in records if r.get("pending_clear_fields")}
    return {"available_clear_actions": actions,
            "pending_changes": [{"report_id":r["report_id"],"shelter_name":r.get("shelter_name"),"village":r.get("village"),
                                 "field":field,"current_value":r.get(field),"proposed_value":None,
                                 "provenance":r.get("field_provenance",{}).get(field)} for r in records for field in r.get("pending_clear_fields",[])],
            "clear_request_template": {"approved_clear_fields": actions, "confirmed_clear_fields": True},
            "decision_choices": ["clear", "keep", "defer"],
            "instruction": "Gunakan report_id persis. Pilih aksi setelah jawaban petugas; officer_note bukan perintah clear. Jangan membuang aksi yang ditolak saat retry."}


def resolve_clear_decisions(data, records):
    """Setiap usulan harus memiliki aksi eksplisit; absennya parameter bukan keputusan keep."""
    options = clear_options(records)["available_clear_actions"]
    clear = data.get("approved_clear_fields", {})
    decisions = data.get("clear_decisions", {})
    if not isinstance(clear, dict) or not isinstance(decisions, dict):
        raise ValueError("approved_clear_fields/clear_decisions harus object dengan key report_id persis.")
    if (set(clear) | set(decisions)) - set(options):
        raise ValueError("Usulan clear tidak mengacu record snapshot. Gunakan available_clear_actions; jangan tambahkan kata 'snapshot' pada ID.")
    resolved = {}
    for rid, fields in options.items():
        selected = clear.get(rid, [])
        choices = decisions.get(rid, {})
        if not isinstance(selected, list) or any(f not in fields for f in selected) or not isinstance(choices, dict) or set(choices) - set(fields):
            raise ValueError("Field keputusan clear tidak ada pada usulan snapshot.")
        resolved[rid] = {}
        for field in fields:
            action = choices.get(field, "clear" if field in selected else None)
            if action not in ("clear", "keep", "defer"):
                raise ValueError(f"Usulan {rid}.{field} belum diputuskan. Deklarasikan clear/keep/defer setelah petugas memilih; catatan saja tidak cukup.")
            if field in selected and action != "clear":
                raise ValueError("approved_clear_fields bertentangan dengan clear_decisions.")
            if action == "clear" and (field not in selected or data.get("confirmed_clear_fields") is not True):
                raise ValueError("Aksi clear membutuhkan approved_clear_fields dan confirmed_clear_fields=true.")
            if action != "clear" and data.get("confirmed_clear_decisions") is not True:
                raise ValueError("Keep/defer membutuhkan keputusan petugas eksplisit: confirmed_clear_decisions=true.")
            resolved[rid][field] = action
    return clear, resolved


def verify_readback(expected, actual):
    """Bandingkan record/aksi yang disetujui, bukan sekadar jumlah baris."""
    def identity(record):
        if record.get("shelter_id"):
            return (record.get("disaster_id") or "", record["shelter_id"])
        normalize = lambda value: " ".join(w for w in re.findall(r"[a-z0-9]+", str(value or "").lower()) if w not in {"posko","desa","kelurahan","pengungsian","tenda"})
        return (normalize(record.get("shelter_name")),normalize(record.get("village")))
    def scalar(value):
        return None if value == "" else value
    def item(value):
        if isinstance(value,dict):
            return value.get("item","") + (f" ({value['qty']} {value.get('unit') or ''})".rstrip() if value.get("qty") else "")
        return str(value)
    indexed = {}
    for record in actual:
        indexed.setdefault(identity(record),[]).append(record)
    differences, matched = [], 0
    fields = ("batch_id","report_id","shelter_type","total_people","total_families","male","female","infants_toddlers","children","elderly","pregnant","breastfeeding","disability","is_estimate","validation_status")
    for record in expected.get("records",[]):
        matches = indexed.get(identity(record),[])
        rid = record.get("report_id")
        if len(matches) != 1:
            differences.append({"report_id":rid,"field":"identity","reason":"record hilang/ambigu"})
            continue
        observed, matched = matches[0], matched+1
        for field in fields:
            if record.get(field) is not None and scalar(observed.get(field)) != scalar(record[field]):
                differences.append({"report_id":rid,"field":field,"expected":record[field],"actual":observed.get(field)})
        if record.get("reported_at"):
            try:
                times=[]
                for value in (record["reported_at"],observed.get("reported_at")):
                    parsed=datetime.fromisoformat(str(value))
                    times.append((parsed.replace(tzinfo=timezone(timedelta(hours=7))) if parsed.tzinfo is None else parsed).timestamp())
                if times[0] != times[1]:
                    differences.append({"report_id":rid,"field":"reported_at","reason":"waktu laporan berbeda"})
            except ValueError:
                differences.append({"report_id":rid,"field":"reported_at","reason":"waktu laporan tidak valid/hilang"})
        for correction in record.get("corrections",[]):
            field = correction.get("field")
            if correction.get("action") == "cleared_by_officer" and record.get(field) is None and scalar(observed.get(field)) is not None:
                differences.append({"report_id":rid,"field":field,"reason":"clear disetujui tetapi belum diterapkan","actual":observed.get(field)})
        for key,amount in (record.get("stock") or {}).items():
            if amount is not None and (observed.get("stock") or {}).get(key) != amount:
                differences.append({"report_id":rid,"field":"stock."+key,"expected":amount,"actual":(observed.get("stock") or {}).get(key)})
            if amount is not None and (observed.get("stock_context") or {}).get(key) != (record.get("stock_context") or {}).get(key):
                differences.append({"report_id":rid,"field":"stock_context."+key,"reason":"metadata stok berbeda"})
        for field in ("urgent_needs","surplus_do_not_send"):
            if record.get(field) or (field == "urgent_needs" and record.get("needs_cleared")):
                if [item(v) for v in record.get(field,[])] != [item(v) for v in observed.get(field,[])]:
                    differences.append({"report_id":rid,"field":field,"reason":"daftar barang berbeda"})
    return {"status":"verified" if not differences else "mismatch", "expected_count":len(expected.get("records",[])),
            "matched_count":matched,"difference_count":len(differences),"differences":differences}


def commit_snapshot(original, effective, storage):
    """Publish revisi hanya sesudah writer sukses; referensi kandidat lama dihentikan."""
    load_snapshot(original)
    payload = dict(effective)
    payload["snapshot_kind"] = "committed"
    payload["parent_snapshot"] = original
    payload["storage"] = storage
    reference = save_snapshot(payload)
    directory = Path(os.environ.get("SIGAP_SNAPSHOT_DIR", "output/.sigap_snapshots")).expanduser()
    target = directory / (original["snapshot_id"] + ".committed.json")
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=directory, delete=False) as stream:
            temporary = stream.name
            json.dump(reference, stream)
        os.replace(temporary, target)
    finally:
        if temporary and os.path.exists(temporary):
            os.unlink(temporary)
    return reference


def save_source(text, correction_target=None, correction_base=None, candidate_target=None):
    payload = {"source_text": text}
    if candidate_target is not None:
        if correction_target is not None or correction_base is not None:
            raise ValueError("Pilih kandidat atau baris tersimpan, bukan kedua target sekaligus.")
        get_candidate_record(candidate_target)
        payload["candidate_target"] = candidate_target
    if correction_target is not None:
        get_correction_record(correction_target)
        payload["correction_target"] = correction_target
    if correction_base is not None:
        if correction_target is None:
            raise ValueError("Kandidat koreksi memerlukan target read-back.")
        get_correction_base(correction_base)
        payload["correction_base"] = correction_base
    reference = save_snapshot(payload)
    return {"batch_id": reference["snapshot_id"], "source_sha256": reference["snapshot_sha256"]}


def load_source(reference):
    return load_source_context(reference)["source_text"]


def load_source_context(reference):
    return load_snapshot({"snapshot_id": reference.get("batch_id"), "snapshot_sha256": reference.get("source_sha256")})


def get_correction_record(target):
    if not isinstance(target, dict):
        raise ValueError("Target koreksi harus referensi read-back.")
    snapshot = load_snapshot({k: target.get(k) for k in ("snapshot_id", "snapshot_sha256")})
    index = target.get("record_index")
    records = snapshot.get("records", [])
    if snapshot.get("snapshot_kind") != "storage_readback" or type(index) is not int or not 0 <= index < len(records):
        raise ValueError("Target koreksi tidak mengacu baris read-back yang sah.")
    record = records[index]
    if not record.get("batch_id") or not record.get("report_id") or not record.get("shelter_name"):
        raise ValueError("Baris asal belum memiliki identitas batch/laporan/posko untuk koreksi.")
    return json.loads(json.dumps(record))


def get_correction_base(reference):
    if not isinstance(reference, dict):
        raise ValueError("Referensi kandidat koreksi tidak valid.")
    snapshot = load_snapshot({k: reference.get(k) for k in ("snapshot_id", "snapshot_sha256")})
    index = reference.get("record_index")
    records = snapshot.get("records", [])
    if snapshot.get("snapshot_kind") != "correction_candidate" or type(index) is not int or not 0 <= index < len(records):
        raise ValueError("Referensi bukan kandidat koreksi yang sah.")
    return json.loads(json.dumps(records[index]))


def get_candidate_record(reference):
    if not isinstance(reference, dict):
        raise ValueError("Target kandidat harus referensi snapshot.")
    snapshot = load_snapshot({k: reference.get(k) for k in ("snapshot_id", "snapshot_sha256")})
    index = reference.get("record_index")
    records = snapshot.get("records", [])
    if snapshot.get("snapshot_kind") not in ("report_candidate", "correction_candidate") or type(index) is not int or not 0 <= index < len(records):
        raise ValueError("Target bukan kandidat yang sah.")
    record = records[index]
    if not record.get("report_id") or not record.get("batch_id") or not record.get("shelter_name"):
        raise ValueError("Kandidat belum memiliki identitas laporan/batch/posko.")
    return json.loads(json.dumps(record))


def matches_update_target(row, header, target):
    """Koreksi menunjuk baris asal; tidak boleh jatuh kembali ke append."""
    if not isinstance(target, dict) or not target.get("batch_id") or not target.get("report_id") or not isinstance(target.get("expected"), dict):
        raise ValueError("Target update tidak valid.")
    columns = {"batch_id": "batch_id", "report_id": "id_laporan", "shelter_name": "posko", "village": "desa", "disaster_id": "disaster_id", "shelter_id": "shelter_id"}
    value = lambda v: "" if v is None else str(v).strip().removeprefix("'")
    for field, column in columns.items():
        actual = row[header.index(column)] if column in header else ""
        if value(actual) != value(target.get(field)):
            return False
    for column, expected in target["expected"].items():
        if column not in header:
            return False
        actual = row[header.index(column)]
        if column in ("waktu_laporan", "dicatat_pada") and expected:
            try:
                times = []
                for item in (actual, expected):
                    parsed = datetime.fromisoformat(str(item))
                    times.append((parsed.replace(tzinfo=timezone(timedelta(hours=7))) if parsed.tzinfo is None else parsed).timestamp())
                if times[0] != times[1]:
                    return False
            except (ValueError, TypeError):
                return False
        elif isinstance(expected, bool):
            if value(actual).lower() != str(expected).lower():
                return False
        elif isinstance(expected, (dict, list)):
            try:
                if json.loads(actual) != expected:
                    return False
            except (ValueError, TypeError):
                return False
        elif value(actual) != value(expected):
            return False
    return True


STOCK_ALIASES = {"water": "air_liter_per_hari", "food": "kkal_per_hari", "latrines": "jamban_unit", "shelter_area": "ruang_hunian_m2"}
STOCK_UNITS = {"air_liter_per_hari": "L", "kkal_per_hari": "kkal", "jamban_unit": "unit", "ruang_hunian_m2": "m2"}


def normalize_stock(record):
    """Normalisasi alias eksplisit tanpa konversi ukuran atau periode."""
    stock, context, issues = {}, {}, []
    raw_stock, raw_context = record.get("stock") or {}, record.get("stock_context") or {}
    if not isinstance(raw_stock, dict) or not isinstance(raw_context, dict):
        return {}, {}, ["stock dan stock_context harus object."]
    for original in set(raw_stock) | set(raw_context):
        key = STOCK_ALIASES.get(original, original)
        if key not in STOCK_UNITS:
            issues.append(f"Key stok tidak dikenal: {original}.")
            continue
        meta = raw_context.get(original) or {}
        if not isinstance(meta, dict):
            issues.append(f"Metadata stok {original} harus object.")
            continue
        amount = raw_stock.get(original, meta.get("value"))
        if key in stock:
            issues.append(f"Alias stok ganda/ambigu untuk {key}.")
            stock[key] = None
            continue
        meta = dict(meta)
        meta.pop("value", None)
        unit = str(meta.get("unit") or "")
        meta["unit"] = {"liter": "L", "litre": "L", "l": "L", "m²": "m2"}.get(unit.lower(), unit)
        if amount is not None and (isinstance(amount, bool) or not isinstance(amount, (int, float)) or not math.isfinite(amount) or amount < 0):
            issues.append(f"Stok {key} harus angka finite nonnegatif.")
            amount = None
        stock[key], context[key] = amount, meta
    return stock, context, issues


def merge_storage_json_cells(old, incoming, merged, header):
    """Metadata parsial di storage mengikuti aturan nilai tidak disebut, bukan replace object."""
    def get(row, column, default):
        if column not in header:
            return default
        value = row[header.index(column)]
        parsed = json.loads(value) if value else default
        if not isinstance(parsed, type(default)):
            raise ValueError(f"Metadata {column} tidak valid.")
        return parsed
    def put(column, value):
        if column in header:
            merged[header.index(column)] = json.dumps(value, ensure_ascii=False, sort_keys=True)
    if "stok_json" in header:
        before, after = get(old,"stok_json",{}), get(incoming,"stok_json",{})
        issues = get(incoming,"masalah_stok_json",[])
        changed = {k for k,v in after.items() if v is not None or any(k in str(issue) for issue in issues)}
        combined = dict(before)
        combined.update({k: after[k] for k in changed})
        put("stok_json", combined)
        context = dict(get(old,"konteks_stok_json",{}))
        new_context = get(incoming,"konteks_stok_json",{})
        context.update({k:new_context.get(k,{}) for k in changed})
        put("konteks_stok_json",context)
    if "provenance_json" in header:
        proof = dict(get(old,"provenance_json",{}))
        new_proof = get(incoming,"provenance_json",{})
        for key,value in new_proof.items():
            # Stok placeholder tidak boleh mengganti provenance nilai lama.
            if key.startswith("stock.") and "stok_json" in header and key[6:] not in changed:
                continue
            proof[key] = value
        put("provenance_json",proof)
    for column in ("riwayat_catatan_json", "riwayat_koreksi_json", "sumber_laporan_json"):
        if column in header:
            values = get(old,column,[]) + get(incoming,column,[])
            unique = {json.dumps(v,sort_keys=True,ensure_ascii=False):v for v in values}
            put(column,list(unique.values()))
    return merged

"""SQLite rekap owner: Langflow. No model-generated SQL or direct browser access."""
import hashlib
import json
import os
import re
import sqlite3
import uuid
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path


def database_path(path=None):
    return Path(path or os.environ.get('SIGAP_SHELTER_DB_PATH', 'output/rekap_posko.sqlite3')).expanduser().resolve()


@contextmanager
def connect_storage(path=None):
    location = database_path(path)
    location.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(str(location), timeout=15, isolation_level=None)
    try:
        db.execute('PRAGMA journal_mode=WAL')
        db.execute('PRAGMA foreign_keys=ON')
        db.executescript('''
          CREATE TABLE IF NOT EXISTS storage_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
          CREATE TABLE IF NOT EXISTS shelters (
            identity TEXT PRIMARY KEY, row_json TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0));
          CREATE TABLE IF NOT EXISTS shelter_history (
            id INTEGER PRIMARY KEY, identity TEXT NOT NULL, before_json TEXT,
            after_json TEXT NOT NULL, commit_key TEXT NOT NULL, saved_at TEXT NOT NULL);
          CREATE TABLE IF NOT EXISTS storage_commits (
            commit_key TEXT PRIMARY KEY, payload_sha256 TEXT NOT NULL, result_json TEXT NOT NULL);
        ''')
        yield db
    finally:
        db.close()


def identity_for(header, row, allow_incomplete=False):
    get = lambda name: str(row[header.index(name)] or '').strip() if name in header else ''
    norm = lambda s: ' '.join(re.findall(r'\w+', s.casefold()))
    disaster, shelter = get('disaster_id'), get('shelter_id')
    if shelter:
        return json.dumps([disaster, 'id', shelter], ensure_ascii=False)
    name, village = norm(get('posko')), norm(get('desa'))
    if not name or not village or village in ('?', 'belum diketahui'):
        if allow_incomplete:
            # Preserve incomplete historical rows without inventing a village or public shelter ID.
            return json.dumps([disaster,'legacy',get('batch_id'),get('id_laporan'),name],ensure_ascii=False)
        raise ValueError('Identitas posko/desa belum lengkap; klarifikasi sebelum menyimpan.')
    return json.dumps([disaster, 'name', name, village], ensure_ascii=False)


def read_sqlite(path=None):
    with connect_storage(path) as db:
        db.execute('BEGIN')
        header = db.execute("SELECT value FROM storage_meta WHERE key='header'").fetchone()
        rows = [json.loads(r[0]) for r in db.execute('SELECT row_json FROM shelters ORDER BY rowid')]
        db.commit()
    return {'header': json.loads(header[0]) if header else [], 'rows': rows, 'count': len(rows), 'path': str(database_path(path))}


def write_sqlite(payload, path, match, merge, *, migration=False):
    """One transaction covers every row, history and idempotency receipt."""
    header = payload['header']
    rows = payload['rows']
    if not header or len(set(header)) != len(header) or any(len(row) != len(header) for row in rows):
        raise ValueError('Schema/baris penyimpanan tidak valid.')
    approved = payload.get('approved_write')
    if not migration and not approved:
        raise ValueError('SQLite hanya menerima baris dari snapshot yang disetujui.')
    digest = hashlib.sha256(json.dumps({k:payload.get(k) for k in ('header','rows','clear_columns','update_targets')},sort_keys=True,ensure_ascii=False).encode()).hexdigest()
    commit_key = json.dumps(approved['source_snapshot'],sort_keys=True) if approved else 'migration:' + digest
    stamp = datetime.now(timezone.utc).isoformat(timespec='seconds')
    output_header = header if migration else header + ['versi','disimpan_di']
    with connect_storage(path) as db:
        db.execute('BEGIN IMMEDIATE')
        try:
            prior = db.execute('SELECT payload_sha256,result_json FROM storage_commits WHERE commit_key=?',(commit_key,)).fetchone()
            if prior:
                if prior[0] != digest:
                    raise ValueError('Snapshot sudah disimpan dengan keputusan berbeda.')
                db.rollback()
                return {**json.loads(prior[1]), 'replayed': True}
            meta = db.execute("SELECT value FROM storage_meta WHERE key='header'").fetchone()
            old_header = json.loads(meta[0]) if meta else output_header
            if old_header != output_header and not set(old_header).issubset(output_header):
                raise ValueError('Schema SQLite berbeda; migrasi eksplisit diperlukan.')
            existing = [(r[0],json.loads(r[1]),r[2]) for r in db.execute('SELECT identity,row_json,version FROM shelters ORDER BY rowid')]
            if migration and existing:
                raise ValueError('Migrasi awal hanya boleh ke database rekap kosong.')
            existing = [(key,[row[old_header.index(c)] if c in old_header else '' for c in output_header],version) for key,row,version in existing]
            # Persist additive header expansion for untouched shelters as well.
            for key,row,version in existing:
                db.execute('UPDATE shelters SET row_json=? WHERE identity=?',(json.dumps(row,ensure_ascii=False),key))
            appended = updated = 0
            seen = set()
            for index,row in enumerate(rows):
                target = payload.get('update_targets',[None]*len(rows))[index]
                # Existing rows include storage metadata (versi/disimpan_di). Targets
                # read from storage can bind these columns too; use their actual schema.
                matches = [(key,old,version) for key,old,version in existing if match(row,old,output_header,target)]
                if len(matches)>1 or target and len(matches)!=1:
                    raise ValueError('Target posko berubah/hilang/ambigu. Baca ulang dan setujui kandidat baru.')
                key = matches[0][0] if matches else identity_for(header,row,allow_incomplete=migration)
                if key in seen:
                    raise ValueError('Posko duplikat dalam satu batch; selesaikan konflik sebelum menyimpan.')
                seen.add(key)
                old = matches[0][1] if matches else None
                new_identity=identity_for(header,row,allow_incomplete=migration or bool(target))
                if any(other_key!=key and identity_for(output_header,other_row,allow_incomplete=True)==new_identity for other_key,other_row,_ in existing):
                    raise ValueError('Perubahan identitas bertabrakan dengan posko lain.')
                if not migration:
                    record = approved['effective_payload']['records'][index]
                    source=record.get('storage_source')
                    if source and (source.get('mode')!='sqlite' or database_path(source.get('path'))!=database_path(path)):
                        raise ValueError('Database writer berbeda dari sumber yang ditinjau petugas.')
                    baseline = record.get('storage_baseline')
                    if baseline:
                        current = dict(zip(output_header,old)) if old else None
                        if current != baseline['row']:
                            raise ValueError('Rekap berubah sejak pratinjau. Baca ulang dan validasi kembali sebelum simpan.')
                    elif old and not target:
                        raise ValueError('Pembaruan belum dibandingkan dengan rekap SQLite. Validasi ulang kandidat.')
                version = matches[0][2]+1 if matches else 1
                if migration:
                    out = row
                    version = int(row[header.index('versi')] or 1) if 'versi' in header else 1
                else:
                    clear = payload.get('clear_columns',[[]]*len(rows))[index]
                    out = (merge(old,row,header,clear) if old else ['' if value is None else str(value) for value in row]) + [str(version),stamp]
                if old: updated += 1
                else: appended += 1
                db.execute('INSERT INTO shelters VALUES(?,?,?) ON CONFLICT(identity) DO UPDATE SET row_json=excluded.row_json,version=excluded.version',(key,json.dumps(out,ensure_ascii=False),version))
                db.execute('INSERT INTO shelter_history(identity,before_json,after_json,commit_key,saved_at) VALUES(?,?,?,?,?)',(key,json.dumps(old,ensure_ascii=False) if old else None,json.dumps(out,ensure_ascii=False),commit_key,stamp))
                existing = [item for item in existing if item[0]!=key]+[(key,out,version)]
            db.execute("INSERT INTO storage_meta VALUES('header',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",(json.dumps(output_header),))
            result = {'path':str(database_path(path)),'count':len(rows),'appended':appended,'updated':updated,'replayed':False}
            db.execute('INSERT INTO storage_commits VALUES(?,?,?)',(commit_key,digest,json.dumps(result)))
            db.commit()
            return result
        except BaseException:
            db.rollback()
            raise


def compare_stored(records, stored):
    """Attach exact baseline row for optimistic concurrency and human field decisions."""
    if not stored['rows']:
        for record in records:
            record['shelter_id'] = record.get('shelter_id') or uuid.uuid4().hex
        return records
    header = stored['header']
    columns = {'total_people':'jumlah_jiwa','male':'laki_laki','female':'perempuan','elderly':'lansia','disability':'disabilitas',
               'total_families':'jumlah_kk','infants_toddlers':'bayi_balita','children':'anak','pregnant':'ibu_hamil','breastfeeding':'ibu_menyusui',
               'urgent_needs':'kebutuhan_mendesak','surplus_do_not_send':'sudah_cukup','notes':'catatan','stock':'stok_json','stock_context':'konteks_stok_json','shelter_type':'jenis_pengungsian'}
    for record in records:
        target=record.get('update_target')
        if target:
            # Renames/village changes compare against the original bound row, not the new label.
            target_probe=[target.get({'posko':'shelter_name','desa':'village','id_laporan':'report_id'}.get(c,c)) for c in header]
            key=identity_for(header,target_probe,allow_incomplete=True)
        else:
            probe = [record.get({'posko':'shelter_name','desa':'village'}.get(c,c)) for c in header]
            try: key = identity_for(header,probe)
            except ValueError: continue
        matches = [row for row in stored['rows'] if identity_for(header,row,allow_incomplete=True)==key]
        if not target and not record.get('shelter_id'):
            norm=lambda value: ' '.join(re.findall(r'\w+',str(value or '').casefold()))
            def same_location(row):
                cells=dict(zip(header,row))
                return norm(cells.get('posko'))==norm(record.get('shelter_name')) and norm(cells.get('desa'))==norm(record.get('village')) and norm(cells.get('disaster_id'))==norm(record.get('disaster_id'))
            matches=[row for row in stored['rows'] if same_location(row)]
            if matches: key=identity_for(header,matches[0],allow_incomplete=True)
        if len(matches)>1: raise ValueError('Data tersimpan memiliki identitas posko ambigu.')
        baseline={'identity':key,'row':dict(zip(header,matches[0])) if matches else None}
        if record.get('storage_baseline') and record['storage_baseline']!=baseline:
            raise ValueError('Rekap tersimpan berubah sejak kandidat pertama. Baca ulang sebelum koreksi.')
        record['storage_baseline']=baseline
        record['validation_issues']=[i for i in record.get('validation_issues',[]) if i.get('field')!='storage_conflicts']
        if not matches:
            record['shelter_id']=record.get('shelter_id') or uuid.uuid4().hex
            continue
        cells = dict(zip(header,matches[0]))
        # Preserve an existing ID; allocate legacy IDs only on an explicitly bound correction.
        # Untargeted legacy updates keep their original location identity until reviewed.
        if cells.get('shelter_id'):record['shelter_id']=cells['shelter_id']
        elif target:record['shelter_id']=record.get('shelter_id') or uuid.uuid4().hex
        old = {field:cells.get(column) for field,column in columns.items()}
        for field in list(columns)[:10]:
            value=old.get(field)
            old[field]=int(value) if value not in (None,'') else None
        for field in ('urgent_needs','surplus_do_not_send'):
            old[field]=[v.strip() for v in (old.get(field) or '').split(';') if v.strip()]
        for field in ('stock','stock_context'):
            old[field]=json.loads(old.get(field) or '{}')
        old['reported_at']=cells.get('waktu_laporan')
        old['field_provenance']=json.loads(cells.get('provenance_json') or '{}')
        conflicts = []
        for field,column in columns.items():
            before,after = old.get(field),record.get(field)
            if field in ('stock','stock_context') and isinstance(after,dict):
                active={k:v for k,v in after.items() if v not in (None,'',{})}
                different=any(before.get(k) is not None and before.get(k)!=v for k,v in active.items()) if isinstance(before,dict) else False
            elif field in ('urgent_needs','surplus_do_not_send'):
                item_text=lambda items:[(v.get('item','')+(f" ({v['qty']} {v.get('unit') or ''})".rstrip() if v.get('qty') else '')) if isinstance(v,dict) else str(v) for v in (items or [])]
                different=item_text(before)!=item_text(after)
            else:different=before!=after
            if before not in (None,'',[],{}) and after not in (None,'',[],{}) and different:
                conflicts.append({'field':field,'previous_value':before,'incoming_value':after,'previous_reported_at':old.get('reported_at'),'incoming_reported_at':record.get('reported_at'),'previous_provenance':old.get('field_provenance',{}).get(field),'incoming_provenance':record.get('field_provenance',{}).get(field)})
        record['storage_conflicts']=conflicts
        if conflicts:
            record.setdefault('validation_issues',[]).append({'field':'storage_conflicts','reason':'Nilai berbeda dengan rekap tersimpan; petugas wajib memilih nilai lama atau baru sebelum simpan.'})
    return records


def resolve_storage_conflicts(records, decisions):
    expected = {r['report_id']:{c['field'] for c in r.get('storage_conflicts',[])} for r in records}
    if not isinstance(decisions,dict) or any(not isinstance(values,dict) or set(values)-expected.get(report,set()) for report,values in decisions.items()):
        raise ValueError('Keputusan konflik mengacu field yang tidak ada pada pratinjau.')
    for record in records:
        for conflict in record.get('storage_conflicts',[]):
            field = conflict['field']
            choice = decisions.get(record['report_id'],{}).get(field)
            if choice not in ('keep','incoming'):
                raise ValueError(f'Putuskan konflik {record["report_id"]} {field}: keep atau incoming.')
            if choice=='keep':
                record[field]=conflict['previous_value']
                if conflict.get('previous_provenance'):
                    record.setdefault('field_provenance',{})[field]=conflict['previous_provenance']
                else:
                    record.setdefault('field_provenance',{}).pop(field,None)
            record.setdefault('corrections',[]).append({**conflict,'action':choice,'value':record.get(field)})
        record['storage_conflicts']=[]
        record['validation_issues']=[i for i in record.get('validation_issues',[]) if i.get('field')!='storage_conflicts']
        if all(isinstance(record.get(k),int) for k in ('total_people','male','female')) and record['male']+record['female']!=record['total_people']:
            # Existing partial snapshots may already contain this issue. Conflict decisions must not create it anew.
            if expected.get(record['report_id']):
                raise ValueError('Pilihan konflik menghasilkan laki-laki + perempuan berbeda dengan jumlah jiwa. Periksa pilihan atau klarifikasi dulu.')
    return records

"""Scoped Supabase transport. Capabilities arrive from the authenticated backend, never the LLM."""
import contextvars
import functools
import hashlib
import json
import os
import re
import secrets
import tempfile
import time
import urllib.request
from pathlib import Path

_cloud_capability = contextvars.ContextVar('sigap_cloud_capability', default=None)

def cloud_request(action, args=None):
    cap = _cloud_capability.get()
    if not cap:
        raise ValueError('Authenticated backend capability is required.')
    # The deployment injects this fixed backend URL, never a URL from model/tool input.
    url = os.environ.get('SIGAP_BACKEND_INTERNAL_URL', 'http://127.0.0.1:8787') + '/api/internal/langflow'
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs):
            return None
    request = urllib.request.Request(url, data=json.dumps({'action': action, 'args': args or {}}, ensure_ascii=False).encode(),
        headers={'Content-Type': 'application/json', 'x-sigap-capability': cap}, method='POST')
    try:
        with urllib.request.build_opener(NoRedirect()).open(request, timeout=30) as response:
            return json.loads(response.read(8 * 1024 * 1024))['data']
    except Exception:
        raise ValueError('Supabase operation rejected or unavailable. No fallback storage.') from None

def authenticated_component(method):
    @functools.wraps(method)
    def guarded(self, *args, **kwargs):
        raw = getattr(self, 'sigap_context', '')
        raw = raw.text if hasattr(raw, 'text') else str(raw or '')
        try:
            envelope = json.loads(raw)
            cap = envelope['__sigap_context']
            if not isinstance(cap, str) or len(cap) > 16384:
                raise ValueError()
        except Exception:
            raise ValueError('SIGAP requires a signed login context from the backend.') from None
        # Every custom node receives the original Chat Input on this separate connection.
        # Only unwrap actual source input fields, never put the capability into a model prompt.
        for field in ('raw_text', 'payload', 'records_json', 'query', 'content', 'input_value'):
            value = getattr(self, field, None)
            text = value.text if hasattr(value, 'text') else str(value or '')
            if text == raw:
                setattr(self, field, envelope['input'])
        token = _cloud_capability.set(cap)
        try:
            return method(self, *args, **kwargs)
        finally:
            _cloud_capability.reset(token)
    return guarded

def cloud_scope():
    cap = _cloud_capability.get()
    if not cap:
        raise ValueError('Missing authenticated context.')
    import base64
    # Decoding selects a namespace only; backend verifies its signature and live membership.
    claims = json.loads(base64.urlsafe_b64decode(cap.split('.')[0] + '==='))
    return 'supabase://' + claims['organization_id'] + '/' + claims['context_id']

def cloud_save_snapshot(payload):
    identifier = secrets.token_hex(16)
    digest = snapshot_digest(payload)
    cloud_request('flow.save', {'id': identifier, 'envelope': {'created_at': time.time(), 'sha256': digest, 'payload': payload}})
    return {'snapshot_id': identifier, 'snapshot_sha256': digest}

def cloud_load_snapshot(request):
    if not isinstance(request, dict) or not re.fullmatch('[a-f0-9]{32}', str(request.get('snapshot_id', ''))):
        raise ValueError('Use a server-issued snapshot reference.')
    if any(k in request for k in ('records', 'stock', 'stock_context', 'snapshot_records')):
        raise ValueError('Free records cannot replace a snapshot.')
    result = cloud_request('flow.load', {'id': request['snapshot_id']})
    if not result or result.get('committed_reference'):
        raise ValueError('Snapshot is missing, outside scope or superseded. Read back current data.')
    envelope = result['envelope']
    if time.time() - envelope['created_at'] > 86400:
        raise ValueError('Snapshot expired.')
    if snapshot_digest(envelope['payload']) != envelope['sha256'] or request.get('snapshot_sha256') != envelope['sha256']:
        raise ValueError('Snapshot hash mismatch.')
    return envelope['payload']

def cloud_commit_snapshot(original, effective, storage):
    cloud_load_snapshot(original)
    payload = dict(effective, snapshot_kind='committed', parent_snapshot=original, storage=storage)
    reference = cloud_save_snapshot(payload)
    if not cloud_request('flow.commit', {'id': original['snapshot_id'], 'reference': reference}):
        raise ValueError('Commit reference changed. Read back, do not retry write.')
    return reference

def cloud_read_storage(path=None):
    result = cloud_request('storage.read')
    document = result['document']
    return {**document, 'count': len(document['rows']), 'path': cloud_scope(), 'revision': result['revision']}

def cloud_write_storage(payload, path, match, merge, *, migration=False):
    if migration:
        raise ValueError('Administrative migration must use the separate reviewed importer.')
    approved = payload.get('approved_write')
    if not approved:
        raise ValueError('Explicit officer approval is required.')
    digest = hashlib.sha256(json.dumps({k: payload.get(k) for k in ('header','rows','clear_columns','update_targets')}, sort_keys=True, ensure_ascii=False).encode()).hexdigest()
    commit_key = json.dumps(approved['source_snapshot'], sort_keys=True)
    receipt = cloud_request('storage.receipt', {'commit_key': commit_key, 'request_hash': digest, 'source_snapshot': approved['source_snapshot']})
    if receipt:
        return receipt
    stored = cloud_read_storage()
    document = {'header': stored['header'], 'rows': stored['rows']}
    scoped_payload = json.loads(json.dumps(payload))
    original_records = scoped_payload['approved_write']['effective_payload']['records']
    for record in original_records:
        source = record.get('storage_source')
        if not source or source.get('mode') != 'supabase' or source.get('path') != cloud_scope():
            raise ValueError('Write scope differs from the reviewed source.')
    # Reuse the existing merge/baseline validator in disposable scratch space.
    # Supabase is the authoritative store; CAS commits rows, history and receipt atomically.
    with tempfile.TemporaryDirectory(prefix='sigap-merge-') as directory:
        local = str(Path(directory) / 'scratch.db')
        with connect_storage(local) as db:
            db.execute('insert into storage_meta values(?,?)', ('header', json.dumps(document['header'])))
            for row in document['rows']:
                key = identity_for(document['header'], row, allow_incomplete=True)
                version = int(row[document['header'].index('versi')] or 1) if 'versi' in document['header'] else 1
                db.execute('insert into shelters values(?,?,?)', (key, json.dumps(row), version))
        for record in original_records:
            record['storage_source'] = {'mode': 'sqlite', 'path': local}
        result = _local_write_storage(scoped_payload, local, match, merge)
        after = _local_read_storage(local)
    result['path'] = cloud_scope()
    return cloud_request('storage.commit', {'revision': stored['revision'], 'document': {'header': after['header'], 'rows': after['rows']},
        'request_hash': digest, 'commit_key': commit_key,
        'source_snapshot': approved['source_snapshot'], 'result': result})

_local_read_storage=read_sqlite
_local_write_storage=write_sqlite
save_snapshot=cloud_save_snapshot
load_snapshot=cloud_load_snapshot
commit_snapshot=cloud_commit_snapshot
read_sqlite=cloud_read_storage
write_sqlite=cloud_write_storage
